def countOrderings(n, rules):
    M = 1000000007
    pred = [0] * n
    for a, b in rules:
        pred[b] |= 1 << a
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        w = dp[mask]
        if not w:
            continue
        for v in range(n):
            if not (mask >> v) & 1 and (pred[v] & mask) == pred[v]:
                nm = mask | (1 << v)
                dp[nm] = (dp[nm] + w) % M
    return dp[(1 << n) - 1]
